INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (101,'myth-01','গোল্ডফিশের স্মৃতি মাত্র ৩ সেকেন্ড','“গোল্ডফিশের স্মৃতি মাত্র ৩ সেকেন্ড”, কথাটা কি সত্যি?','myth','গোল্ডফিশ বেশ ভালো মনে রাখে। গবেষকদের মতে তাদের স্মৃতি সপ্তাহ থেকে মাস, এমনকি বছরও টিকতে পারে।','["মিথ! গোল্ডফিশ বেশ ভালো মনে রাখে। গবেষকদের মতে তাদের স্মৃতি সপ্তাহ থেকে মাস, এমনকি বছরও টিকতে পারে।", "কেন এমন?\\n১) গবেষকদের মতে গোল্ডফিশের স্মৃতি সপ্তাহ, মাস, এমনকি বছরও টিকতে পারে।\\n২) আকার, রং আর শব্দ আলাদা করে চিনতে শিখতে পারে।\\n৩) কয়েক সপ্তাহ বা মাস পরে হাত থেকে খাবার নিতেও আর ভয় পায় না।"]','[{"label": "Live Science", "url": "https://www.livescience.com/goldfish-memory.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Goldfish"}]','[{"src": "/media/myth-na-sotti/myth-01-1.webp", "width": 960, "height": 1200, "alt": "গোল্ডফিশের স্মৃতি মাত্র ৩ সেকেন্ড, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-01-2.webp", "width": 960, "height": 1200, "alt": "গোল্ডফিশের স্মৃতি মাত্র ৩ সেকেন্ড, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-01-3.webp", "width": 960, "height": 1200, "alt": "গোল্ডফিশের স্মৃতি মাত্র ৩ সেকেন্ড, কার্ড 3"}]','2026-12-05');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (102,'myth-02','উটের কুঁজে পানি জমা থাকে','“উটের কুঁজে পানি জমা থাকে”, কথাটা কি সত্যি?','myth','কুঁজে থাকে চর্বি, পানি নয়। খাবার কমে গেলে উট সেই চর্বি থেকেই শক্তি পায়।','["মিথ! কুঁজে থাকে চর্বি, পানি নয়। খাবার কমে গেলে উট সেই চর্বি থেকেই শক্তি পায়।", "কেন এমন?\\n১) কুঁজ আসলে আঁশযুক্ত কোষে বাঁধা চর্বি।\\n২) চর্বি ফুরিয়ে এলে ফাঁকা কুঁজ ফুটো বেলুনের মতো কাত হয়ে পড়ে।\\n৩) ছানা উট কুঁজের চর্বি নিয়ে জন্মায় না, মায়ের দুধ খাওয়ার সময়ও তা জমে না।"]','[{"label": "Live Science", "url": "https://www.livescience.com/goldfish-memory.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Goldfish"}]','[{"src": "/media/myth-na-sotti/myth-02-1.webp", "width": 960, "height": 1200, "alt": "উটের কুঁজে পানি জমা থাকে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-02-2.webp", "width": 960, "height": 1200, "alt": "উটের কুঁজে পানি জমা থাকে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-02-3.webp", "width": 960, "height": 1200, "alt": "উটের কুঁজে পানি জমা থাকে, কার্ড 3"}]','2026-12-07');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (103,'myth-03','বাজ একই জায়গায় দুবার পড়ে না','“বাজ একই জায়গায় দুবার পড়ে না”, কথাটা কি সত্যি?','myth','বাজ প্রায়ই একই জায়গায় বারবার পড়ে, বিশেষ করে উঁচু, সরু আর একা দাঁড়ানো জিনিসে।','["মিথ! বাজ প্রায়ই একই জায়গায় বারবার পড়ে, বিশেষ করে উঁচু, সরু আর একা দাঁড়ানো জিনিসে।", "কেন এমন?\\n১) নিউ ইয়র্কের এম্পায়ার স্টেট বিল্ডিংয়ে বছরে গড়ে প্রায় ২৩ বার বাজ পড়ে।\\n২) গাছ আর পাহাড়ের মতো উঁচু ও একা দাঁড়ানো জিনিসেও বছরে বহুবার বাজ পড়ে।\\n৩) তাই বজ্রঝড়ের সময় ঘরের ভেতরে থাকাই নিরাপদ।"]','[{"label": "US National Weather Service", "url": "https://www.weather.gov/safety/lightning-myths"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Lightning"}]','[{"src": "/media/myth-na-sotti/myth-03-1.webp", "width": 960, "height": 1200, "alt": "বাজ একই জায়গায় দুবার পড়ে না, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-03-2.webp", "width": 960, "height": 1200, "alt": "বাজ একই জায়গায় দুবার পড়ে না, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-03-3.webp", "width": 960, "height": 1200, "alt": "বাজ একই জায়গায় দুবার পড়ে না, কার্ড 3"}]','2026-12-12');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (104,'myth-04','আমরা মস্তিষ্কের মাত্র ১০% ব্যবহার করি','“আমরা মস্তিষ্কের মাত্র ১০% ব্যবহার করি”, কথাটা কি সত্যি?','myth','আমরা প্রায় পুরো মস্তিষ্কই ব্যবহার করি। বেশিরভাগ সময়ই মস্তিষ্কের বেশিরভাগ অংশ সক্রিয় থাকে।','["মিথ! আমরা প্রায় পুরো মস্তিষ্কই ব্যবহার করি। বেশিরভাগ সময়ই মস্তিষ্কের বেশিরভাগ অংশ সক্রিয় থাকে।", "কেন এমন?\\n১) স্নায়ুবিজ্ঞানী ব্যারি গর্ডনের কথায়, আমরা মস্তিষ্কের প্রায় প্রতিটি অংশই ব্যবহার করি।\\n২) মস্তিষ্কের এমন অংশ প্রায় নেই, যেটা ক্ষতি হলে কোনো ক্ষমতা হারায় না।\\n৩) নিজের ভুলত্রুটি দেখে মানুষ ভাবে, একটা অংশ অব্যবহৃত পড়ে আছে। এভাবেই ধারণাটা টিকে আছে।"]','[{"label": "Scientific American", "url": "https://www.scientificamerican.com/article/do-people-only-use-10-percent-of-their-brains/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ten_percent_of_the_brain_myth"}]','[{"src": "/media/myth-na-sotti/myth-04-1.webp", "width": 960, "height": 1200, "alt": "আমরা মস্তিষ্কের মাত্র ১০% ব্যবহার করি, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-04-2.webp", "width": 960, "height": 1200, "alt": "আমরা মস্তিষ্কের মাত্র ১০% ব্যবহার করি, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-04-3.webp", "width": 960, "height": 1200, "alt": "আমরা মস্তিষ্কের মাত্র ১০% ব্যবহার করি, কার্ড 3"}]','2026-12-14');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (105,'myth-05','বাদুড় অন্ধ','“বাদুড় অন্ধ”, কথাটা কি সত্যি?','myth','কোনো বাদুড়ই সত্যিকারের অন্ধ নয়। সবাই দেখতে পায়, শুধু প্রজাতিভেদে দৃষ্টিশক্তি আলাদা।','["মিথ! কোনো বাদুড়ই সত্যিকারের অন্ধ নয়। সবাই দেখতে পায়, শুধু প্রজাতিভেদে দৃষ্টিশক্তি আলাদা।", "কেন এমন?\\n১) ছোট বাদুড়ের চোখ ছোট হলেও আলো টের পায়। কোনো প্রজাতিই পুরোপুরি অন্ধ নয়।\\n২) বড় ফলখেকো বাদুড়ের (ফ্লাইং ফক্স) চোখের দৃষ্টি বেশ ভালো।\\n৩) অনেক ছোট বাদুড় অন্ধকারে চলতে শব্দের প্রতিধ্বনিও কাজে লাগায়।"]','[{"label": "Live Science", "url": "https://www.livescience.com/goldfish-memory.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Goldfish"}]','[{"src": "/media/myth-na-sotti/myth-05-1.webp", "width": 960, "height": 1200, "alt": "বাদুড় অন্ধ, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-05-2.webp", "width": 960, "height": 1200, "alt": "বাদুড় অন্ধ, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-05-3.webp", "width": 960, "height": 1200, "alt": "বাদুড় অন্ধ, কার্ড 3"}]','2026-12-19');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (106,'myth-06','কলাগাছ আসলে গাছই নয়','“কলাগাছ আসলে গাছই নয়”, কথাটা কি সত্যি?','true','ঠিক! যেটাকে কাণ্ড ভাবি, সেটা পাতার গোড়া জড়িয়ে তৈরি ‘ভুয়া কাণ্ড’। কলাগাছ আসলে বিশাল এক ওষধি উদ্ভিদ।','["সত্য! ঠিক! যেটাকে কাণ্ড ভাবি, সেটা পাতার গোড়া জড়িয়ে তৈরি ‘ভুয়া কাণ্ড’। কলাগাছ আসলে বিশাল এক ওষধি উদ্ভিদ।", "কেন এমন?\\n১) যেটাকে কাণ্ড ভাবি, সেটা আসলে পাতার বোঁটার গোড়া জড়িয়ে তৈরি ‘সিউডোস্টেম’।\\n২) কাঠের মতো শক্ত কাণ্ড হয় না বলে কলাগাছ বিজ্ঞানের ভাষায় ওষধি জাতীয় উদ্ভিদ।\\n৩) ফুল ফোটা ওষধি উদ্ভিদের মধ্যে কলাগাছই সবচেয়ে বড়।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Banana"}, {"label": "UF/IFAS Extension (St. Lucie County)", "url": "https://blogs.ifas.ufl.edu/stlucieco/2026/10/19/bananas-vs-plantains-similar-fruit-different-uses/"}]','[{"src": "/media/myth-na-sotti/myth-06-1.webp", "width": 960, "height": 1200, "alt": "কলাগাছ আসলে গাছই নয়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-06-2.webp", "width": 960, "height": 1200, "alt": "কলাগাছ আসলে গাছই নয়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-06-3.webp", "width": 960, "height": 1200, "alt": "কলাগাছ আসলে গাছই নয়, কার্ড 3"}]','2026-12-21');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (107,'myth-07','অক্টোপাসের তিনটি হৃদয় আছে','“অক্টোপাসের তিনটি হৃদয় আছে”, কথাটা কি সত্যি?','true','সত্যিই! দুটি হৃদয় ফুলকায় রক্ত পাঠায়, আর তৃতীয়টি সেই রক্ত পুরো শরীরে ছড়ায়।','["সত্য! সত্যিই! দুটি হৃদয় ফুলকায় রক্ত পাঠায়, আর তৃতীয়টি সেই রক্ত পুরো শরীরে ছড়ায়।", "কেন এমন?\\n১) একটি প্রধান হৃদয় রক্ত ঘোরায় পুরো শরীরে।\\n২) বাকি দুটি হৃদয় ফুলকার ভেতর দিয়ে রক্ত পাঠায়।\\n৩) এক অক্টোপাস-জীববিজ্ঞানীর মতে, তিন হৃদয় রক্তের চাপ ঠিক রাখতে সাহায্য করে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/32366-why-do-camels-have-humps.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Dromedary"}]','[{"src": "/media/myth-na-sotti/myth-07-1.webp", "width": 960, "height": 1200, "alt": "অক্টোপাসের তিনটি হৃদয় আছে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-07-2.webp", "width": 960, "height": 1200, "alt": "অক্টোপাসের তিনটি হৃদয় আছে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-07-3.webp", "width": 960, "height": 1200, "alt": "অক্টোপাসের তিনটি হৃদয় আছে, কার্ড 3"}]','2026-12-26');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (108,'myth-08','মহাকাশে চিৎকার করলেও কেউ শুনতে পাবে না','“মহাকাশে চিৎকার করলেও কেউ শুনতে পাবে না”, কথাটা কি সত্যি?','true','সত্যি। শব্দ চলতে বাতাসের মতো কিছু একটা লাগে, আর মহাকাশ প্রায় ফাঁকা।','["সত্য! সত্যি। শব্দ চলতে বাতাসের মতো কিছু একটা লাগে, আর মহাকাশ প্রায় ফাঁকা।", "কেন এমন?\\n১) শব্দ আসলে কম্পন, যা বাতাস, পানি বা কোনো পদার্থের ভেতর দিয়ে ছড়ায়।\\n২) মহাকাশে অণু এত কম যে কম্পন এক অণু থেকে আরেক অণুতে যেতে পারে না।\\n৩) মহাকাশযানের ভেতরে বাতাস আছে, তাই সেখানে কথা শোনা যায়।"]','[{"label": "ESA", "url": "https://www.esa.int/Science_Exploration/Space_Science/Space_sensations/LISTEN_UP"}, {"label": "Live Science", "url": "https://www.livescience.com/space/what-would-space-sound-like-if-we-could-hear-it"}, {"label": "NASA Cosmicopia", "url": "https://cosmicopia.gsfc.nasa.gov/qa_sp_en.html"}]','[{"src": "/media/myth-na-sotti/myth-08-1.webp", "width": 960, "height": 1200, "alt": "মহাকাশে চিৎকার করলেও কেউ শুনতে পাবে না, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-08-2.webp", "width": 960, "height": 1200, "alt": "মহাকাশে চিৎকার করলেও কেউ শুনতে পাবে না, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-08-3.webp", "width": 960, "height": 1200, "alt": "মহাকাশে চিৎকার করলেও কেউ শুনতে পাবে না, কার্ড 3"}]','2026-12-28');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (109,'myth-09','মধু কখনো নষ্ট হয় না','“মধু কখনো নষ্ট হয় না”, কথাটা কি সত্যি?','true','সত্যি, তবে ঠিকভাবে বন্ধ করে রাখলে। প্রচুর চিনি আর অম্লতার কারণে বেশিরভাগ জীবাণু মধুতে বাড়তে পারে না।','["সত্য! সত্যি, তবে ঠিকভাবে বন্ধ করে রাখলে। প্রচুর চিনি আর অম্লতার কারণে বেশিরভাগ জীবাণু মধুতে বাড়তে পারে না।", "কেন এমন?\\n১) ঘন চিনি আর অম্লীয় স্বভাবের কারণে বেশিরভাগ জীবাণু মধুতে বাড়তে পারে না।\\n২) প্রত্নতাত্ত্বিক খননে পাওয়া কয়েক হাজার বছরের পুরনো মধুর নমুনাও খাওয়ার মতো ছিল।\\n৩) মুখ খোলা থাকলে মধু বাতাস থেকে আর্দ্রতা টেনে নেয়, তখন নষ্ট হতে পারে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/chemistry/does-honey-ever-go-bad"}, {"label": "BBC Science Focus", "url": "https://www.sciencefocus.com/science/why-doesnt-honey-go-off"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Honey"}]','[{"src": "/media/myth-na-sotti/myth-09-1.webp", "width": 960, "height": 1200, "alt": "মধু কখনো নষ্ট হয় না, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-09-2.webp", "width": 960, "height": 1200, "alt": "মধু কখনো নষ্ট হয় না, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-09-3.webp", "width": 960, "height": 1200, "alt": "মধু কখনো নষ্ট হয় না, কার্ড 3"}]','2027-01-02');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (110,'myth-10','পৃথিবী সূর্যের কাছে এলে গ্রীষ্ম, দূরে গেলে শীত','“পৃথিবী সূর্যের কাছে এলে গ্রীষ্ম, দূরে গেলে শীত”, কথাটা কি সত্যি?','myth','ঋতু হয় পৃথিবীর অক্ষ হেলে থাকার কারণে, সূর্যের দূরত্বের কারণে নয়।','["মিথ! ঋতু হয় পৃথিবীর অক্ষ হেলে থাকার কারণে, সূর্যের দূরত্বের কারণে নয়।", "কেন এমন?\\n১) পৃথিবীর অক্ষ কক্ষপথের তলের সাথে ২৩.৪ ডিগ্রি হেলে আছে (নাসা)।\\n২) উত্তর মেরু সূর্যের দিকে হেলে থাকলে উত্তর গোলার্ধে গ্রীষ্ম।\\n৩) একই সময়ে দক্ষিণ গোলার্ধে শীত। দূরত্ব কারণ হলে সবখানে একই ঋতু হতো।"]','[{"label": "NASA Space Place", "url": "https://spaceplace.nasa.gov/seasons/en/"}, {"label": "NASA Science", "url": "https://science.nasa.gov/earth/facts/"}]','[{"src": "/media/myth-na-sotti/myth-10-1.webp", "width": 960, "height": 1200, "alt": "পৃথিবী সূর্যের কাছে এলে গ্রীষ্ম, দূরে গেলে শীত, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-10-2.webp", "width": 960, "height": 1200, "alt": "পৃথিবী সূর্যের কাছে এলে গ্রীষ্ম, দূরে গেলে শীত, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-10-3.webp", "width": 960, "height": 1200, "alt": "পৃথিবী সূর্যের কাছে এলে গ্রীষ্ম, দূরে গেলে শীত, কার্ড 3"}]','2027-01-04');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (111,'myth-11','পিঁপড়া কখনো ঘুমায় না','“পিঁপড়া কখনো ঘুমায় না”, কথাটা কি সত্যি?','myth','পিঁপড়াও ঘুমায়, তবে অল্প অল্প করে। এক গবেষণায় আগুন-পিঁপড়ার রানি আর শ্রমিক, দুইয়েরই বারবার ছোট ঘুম ধরা পড়েছে।','["মিথ! পিঁপড়াও ঘুমায়, তবে অল্প অল্প করে। এক গবেষণায় আগুন-পিঁপড়ার রানি আর শ্রমিক, দুইয়েরই বারবার ছোট ঘুম ধরা পড়েছে।", "কেন এমন?\\n১) রানি পিঁপড়া দিনে প্রায় ৯২ বার ঘুমায়, প্রতিবার প্রায় ৬ মিনিট।\\n২) শ্রমিক পিঁপড়া প্রায় ২৫৩ বার ছোট ঘুম দেয়, প্রতিবার প্রায় ১ মিনিট করে।\\n৩) গভীর ঘুমে তারা শুঁড় গুটিয়ে নেয় আর অন্য পিঁপড়ার ছোঁয়ায় সাড়া দেয় না।"]','[{"label": "University of South Florida (Cassill et ", "url": "https://digitalcommons.usf.edu/fac_publications/1010/"}]','[{"src": "/media/myth-na-sotti/myth-11-1.webp", "width": 960, "height": 1200, "alt": "পিঁপড়া কখনো ঘুমায় না, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-11-2.webp", "width": 960, "height": 1200, "alt": "পিঁপড়া কখনো ঘুমায় না, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-11-3.webp", "width": 960, "height": 1200, "alt": "পিঁপড়া কখনো ঘুমায় না, কার্ড 3"}]','2027-01-09');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (112,'myth-12','মাকড়সা একটি পোকা','“মাকড়সা একটি পোকা”, কথাটা কি সত্যি?','myth','মাকড়সা পোকা নয়, আরাকনিড। পোকার ছয় পা আর তিন ভাগের শরীর, মাকড়সার আট পা আর দুই ভাগের শরীর।','["মিথ! মাকড়সা পোকা নয়, আরাকনিড। পোকার ছয় পা আর তিন ভাগের শরীর, মাকড়সার আট পা আর দুই ভাগের শরীর।", "কেন এমন?\\n১) মাকড়সা আরাকনিড দলের প্রাণী। বিচ্ছু আর আঠালি (টিক)-ও এই দলে।\\n২) পোকার শরীর তিন ভাগে, মাকড়সার দুই ভাগে: জোড়া লাগানো মাথা-বুক আর পেট।\\n৩) পোকার শুঁড় আর ডানা থাকে, মাকড়সার কোনোটাই থাকে না।"]','[{"label": "Live Science", "url": "https://www.livescience.com/goldfish-memory.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Goldfish"}]','[{"src": "/media/myth-na-sotti/myth-12-1.webp", "width": 960, "height": 1200, "alt": "মাকড়সা একটি পোকা, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-12-2.webp", "width": 960, "height": 1200, "alt": "মাকড়সা একটি পোকা, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-12-3.webp", "width": 960, "height": 1200, "alt": "মাকড়সা একটি পোকা, কার্ড 3"}]','2027-01-11');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (113,'myth-13','তিমি একটি মাছ','“তিমি একটি মাছ”, কথাটা কি সত্যি?','myth','তিমি মাছ নয়, স্তন্যপায়ী প্রাণী। তারা ফুসফুস দিয়ে শ্বাস নেয় আর বাচ্চাকে দুধ খাওয়ায়।','["মিথ! তিমি মাছ নয়, স্তন্যপায়ী প্রাণী। তারা ফুসফুস দিয়ে শ্বাস নেয় আর বাচ্চাকে দুধ খাওয়ায়।", "কেন এমন?\\n১) তিমি ফুসফুসে বাতাস নিয়ে শ্বাস নেয়, তাই নিয়মিত পানির ওপরে উঠে আসতে হয়।\\n২) তিমি উষ্ণ রক্তের প্রাণী এবং বাচ্চাকে দুধ খাইয়ে বড় করে।\\n৩) তিমির পূর্বপুরুষ ছিল ডাঙার স্তন্যপায়ী প্রাণী।"]','[{"label": "NOAA", "url": "https://www.noaa.gov/education/resource-collections/marine-life/marine-mammals"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Whale"}]','[{"src": "/media/myth-na-sotti/myth-13-1.webp", "width": 960, "height": 1200, "alt": "তিমি একটি মাছ, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-13-2.webp", "width": 960, "height": 1200, "alt": "তিমি একটি মাছ, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-13-3.webp", "width": 960, "height": 1200, "alt": "তিমি একটি মাছ, কার্ড 3"}]','2027-01-16');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (114,'myth-14','পেঁচা মাথা পুরো ৩৬০ ডিগ্রি ঘোরাতে পারে','“পেঁচা মাথা পুরো ৩৬০ ডিগ্রি ঘোরাতে পারে”, কথাটা কি সত্যি?','myth','পুরো ৩৬০ ডিগ্রি নয়। অনেক পেঁচা প্রতি দিকে সর্বোচ্চ প্রায় ২৭০ ডিগ্রি পর্যন্ত মাথা ঘোরাতে পারে।','["মিথ! পুরো ৩৬০ ডিগ্রি নয়। অনেক পেঁচা প্রতি দিকে সর্বোচ্চ প্রায় ২৭০ ডিগ্রি পর্যন্ত মাথা ঘোরাতে পারে।", "কেন এমন?\\n১) বারড পেঁচার মতো অনেক পেঁচা ডানে-বাঁয়ে ২৭০ ডিগ্রি পর্যন্ত মাথা ঘোরায়।\\n২) পেঁচার চোখ খোলের ভেতরে প্রায় স্থির, তাই তাকাতে হলে মাথাই ঘোরাতে হয়।\\n৩) গবেষকদের ধারণা, মাথা ঘোরানোর সময় মস্তিষ্কের রক্তসরবরাহ ঠিক রাখতে বিশেষ রক্তনালী কাজ করে।"]','[{"label": "Scientific American", "url": "https://www.scientificamerican.com/article/do-people-only-use-10-percent-of-their-brains/"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Ten_percent_of_the_brain_myth"}]','[{"src": "/media/myth-na-sotti/myth-14-1.webp", "width": 960, "height": 1200, "alt": "পেঁচা মাথা পুরো ৩৬০ ডিগ্রি ঘোরাতে পারে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-14-2.webp", "width": 960, "height": 1200, "alt": "পেঁচা মাথা পুরো ৩৬০ ডিগ্রি ঘোরাতে পারে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-14-3.webp", "width": 960, "height": 1200, "alt": "পেঁচা মাথা পুরো ৩৬০ ডিগ্রি ঘোরাতে পারে, কার্ড 3"}]','2027-01-18');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (115,'myth-15','ফ্লেমিঙ্গোর গোলাপি রং আসে তাদের খাবার থেকে','“ফ্লেমিঙ্গোর গোলাপি রং আসে তাদের খাবার থেকে”, কথাটা কি সত্যি?','true','সত্যি! শেওলা আর ছোট জলজ প্রাণীর রঞ্জক পদার্থ খেয়েই ফ্লেমিঙ্গোর পালক গোলাপি হয়।','["সত্য! সত্যি! শেওলা আর ছোট জলজ প্রাণীর রঞ্জক পদার্থ খেয়েই ফ্লেমিঙ্গোর পালক গোলাপি হয়।", "কেন এমন?\\n১) খাবারের ক্যারোটিন জাতীয় রঞ্জক পালকে জমে গোলাপি-লাল রং তৈরি করে।\\n২) ফ্লেমিঙ্গোর ছানা জন্মায় ধূসরাভ রঙে, গোলাপি হতে কয়েক বছর লাগে।\\n৩) বন্দি অবস্থায় ক্যারোটিনযুক্ত খাবার না পেলে তারা ফ্যাকাশে গোলাপি হয়ে যেতে পারে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/27322-flamingos.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Flamingo"}]','[{"src": "/media/myth-na-sotti/myth-15-1.webp", "width": 960, "height": 1200, "alt": "ফ্লেমিঙ্গোর গোলাপি রং আসে তাদের খাবার থেকে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-15-2.webp", "width": 960, "height": 1200, "alt": "ফ্লেমিঙ্গোর গোলাপি রং আসে তাদের খাবার থেকে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-15-3.webp", "width": 960, "height": 1200, "alt": "ফ্লেমিঙ্গোর গোলাপি রং আসে তাদের খাবার থেকে, কার্ড 3"}]','2027-01-23');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (116,'myth-16','চাঁদের একটা পিঠ চিরকাল অন্ধকার থাকে','“চাঁদের একটা পিঠ চিরকাল অন্ধকার থাকে”, কথাটা কি সত্যি?','myth','চাঁদের কোনো পিঠই চিরকাল অন্ধকার নয়। যে পিঠ আমরা কখনো দেখি না, সেটাও সূর্যের আলো পায়।','["মিথ! চাঁদের কোনো পিঠই চিরকাল অন্ধকার নয়। যে পিঠ আমরা কখনো দেখি না, সেটাও সূর্যের আলো পায়।", "কেন এমন?\\n১) চাঁদ পৃথিবীকে একবার ঘুরতে নিজের অক্ষেও একবার ঘোরে, তাই একই পিঠ সবসময় পৃথিবীর দিকে থাকে।\\n২) আমরা যে পিঠ দেখি না, সেটার ঠিক নাম ‘দূরের পিঠ’। ‘অন্ধকার পিঠ’ নামটা বিভ্রান্তিকর।\\n৩) পূর্ণিমায় দূরের পিঠ অন্ধকার, আর অমাবস্যায় ঠিক উল্টো: দূরের পিঠেই আলো পড়ে।"]','[{"label": "NOAA", "url": "https://www.noaa.gov/education/resource-collections/marine-life/marine-mammals"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Whale"}]','[{"src": "/media/myth-na-sotti/myth-16-1.webp", "width": 960, "height": 1200, "alt": "চাঁদের একটা পিঠ চিরকাল অন্ধকার থাকে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-16-2.webp", "width": 960, "height": 1200, "alt": "চাঁদের একটা পিঠ চিরকাল অন্ধকার থাকে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-16-3.webp", "width": 960, "height": 1200, "alt": "চাঁদের একটা পিঠ চিরকাল অন্ধকার থাকে, কার্ড 3"}]','2027-01-25');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (117,'myth-17','মহাকাশ থেকে চীনের প্রাচীর দেখা যায়','“মহাকাশ থেকে চীনের প্রাচীর দেখা যায়”, কথাটা কি সত্যি?','myth','নিচু কক্ষপথ থেকেও খালি চোখে দেখা কঠিন বা অসম্ভব। নাসা বলছে, চাঁদ থেকে এটা মোটেই দেখা যায় না।','["মিথ! নিচু কক্ষপথ থেকেও খালি চোখে দেখা কঠিন বা অসম্ভব। নাসা বলছে, চাঁদ থেকে এটা মোটেই দেখা যায় না।", "কেন এমন?\\n১) নাসার মতে, শক্তিশালী লেন্স ছাড়া পৃথিবীর কক্ষপথ থেকে প্রাচীর দেখা কঠিন বা অসম্ভব।\\n২) চীনের প্রথম মহাকাশচারী ইয়াং লিওয়েই ২০০৩ সালে নিজের যাত্রায় প্রাচীর খুঁজে পাননি বলে জানিয়েছেন।\\n৩) সমস্যা রেজোলিউশনের: প্রাচীর সরু আর আশপাশের মাটির মতো রঙের, এত দূর থেকে চোখ তা আলাদা করতে পারে না।"]','[{"label": "NASA", "url": "https://www.nasa.gov/vision/space/workinginspace/great_wall.html"}, {"label": "Live Science", "url": "https://www.livescience.com/34212-great-wall-of-china-only-manmade-object-visible-from-space.html"}, {"label": "Scientific American", "url": "https://www.scientificamerican.com/article/no-you-cant-see-the-great-wall-of-china-from-space/"}]','[{"src": "/media/myth-na-sotti/myth-17-1.webp", "width": 960, "height": 1200, "alt": "মহাকাশ থেকে চীনের প্রাচীর দেখা যায়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-17-2.webp", "width": 960, "height": 1200, "alt": "মহাকাশ থেকে চীনের প্রাচীর দেখা যায়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-17-3.webp", "width": 960, "height": 1200, "alt": "মহাকাশ থেকে চীনের প্রাচীর দেখা যায়, কার্ড 3"}]','2027-01-30');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (118,'myth-18','সূর্য সবসময় ঠিক পূর্ব দিকেই ওঠে','“সূর্য সবসময় ঠিক পূর্ব দিকেই ওঠে”, কথাটা কি সত্যি?','myth','সূর্য ঠিক পূর্বে ওঠে বছরে শুধু দুবার, মার্চ আর সেপ্টেম্বরের বিষুবের সময়। বাকি সময় একটু উত্তরে বা দক্ষিণে সরে যায়।','["মিথ! সূর্য ঠিক পূর্বে ওঠে বছরে শুধু দুবার, মার্চ আর সেপ্টেম্বরের বিষুবের সময়। বাকি সময় একটু উত্তরে বা দক্ষিণে সরে যায়।", "কেন এমন?\\n১) বিষুবের দুই দিনেই সূর্য প্রায় ঠিক পূর্বে ওঠে আর ঠিক পশ্চিমে অস্ত যায়।\\n২) ডিসেম্বরের অয়নান্তে সূর্য ওঠে ঠিক পূর্বের কিছুটা দক্ষিণে।\\n৩) জুনের অয়নান্তে সে ওঠে বছরের সবচেয়ে উত্তরে, ধীরে ধীরে সরতে সরতে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/26771-how-owls-rotate-heads.html"}, {"label": "Audubon", "url": "https://www.audubon.org/magazine/13-fun-facts-about-owls"}]','[{"src": "/media/myth-na-sotti/myth-18-1.webp", "width": 960, "height": 1200, "alt": "সূর্য সবসময় ঠিক পূর্ব দিকেই ওঠে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-18-2.webp", "width": 960, "height": 1200, "alt": "সূর্য সবসময় ঠিক পূর্ব দিকেই ওঠে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-18-3.webp", "width": 960, "height": 1200, "alt": "সূর্য সবসময় ঠিক পূর্ব দিকেই ওঠে, কার্ড 3"}]','2027-02-01');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (119,'myth-19','ধ্রুবতারা আকাশের সবচেয়ে উজ্জ্বল তারা','“ধ্রুবতারা আকাশের সবচেয়ে উজ্জ্বল তারা”, কথাটা কি সত্যি?','myth','ধ্রুবতারা মোটেই সবচেয়ে উজ্জ্বল নয়। রাতের আকাশের সবচেয়ে উজ্জ্বল তারা সিরিয়াস (লুব্ধক)।','["মিথ! ধ্রুবতারা মোটেই সবচেয়ে উজ্জ্বল নয়। রাতের আকাশের সবচেয়ে উজ্জ্বল তারা সিরিয়াস (লুব্ধক)।", "কেন এমন?\\n১) নাসা বলছে, উত্তর তারা আকাশের সবচেয়ে উজ্জ্বল তারা নয়, তবে সহজেই চোখে পড়ে।\\n২) সে বিখ্যাত কারণ প্রায় সবসময় একই জায়গায় থাকে, তাই তাকে দেখে উত্তর দিক চেনা যায়।\\n৩) আকাশের সবচেয়ে উজ্জ্বল তারা সিরিয়াস, ধ্রুবতারা তালিকায় অনেক নিচে।"]','[{"label": "US National Park Service", "url": "https://www.nps.gov/articles/bats-brief.htm"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Bat"}]','[{"src": "/media/myth-na-sotti/myth-19-1.webp", "width": 960, "height": 1200, "alt": "ধ্রুবতারা আকাশের সবচেয়ে উজ্জ্বল তারা, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-19-2.webp", "width": 960, "height": 1200, "alt": "ধ্রুবতারা আকাশের সবচেয়ে উজ্জ্বল তারা, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-19-3.webp", "width": 960, "height": 1200, "alt": "ধ্রুবতারা আকাশের সবচেয়ে উজ্জ্বল তারা, কার্ড 3"}]','2027-02-06');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (120,'myth-20','ব্ল্যাক হোল সবকিছু টেনে নেয়','“ব্ল্যাক হোল সবকিছু টেনে নেয়”, কথাটা কি সত্যি?','myth','দূর থেকে ব্ল্যাক হোল একই ভরের অন্য বস্তুর মতোই টানে। সূর্য ব্ল্যাক হোল হয়ে গেলেও গ্রহদের কক্ষপথ একই থাকত।','["মিথ! দূর থেকে ব্ল্যাক হোল একই ভরের অন্য বস্তুর মতোই টানে। সূর্য ব্ল্যাক হোল হয়ে গেলেও গ্রহদের কক্ষপথ একই থাকত।", "কেন এমন?\\n১) নাসার ভাষায়, টিভি-সিনেমায় ব্ল্যাক হোলকে ‘মহাজাগতিক ভ্যাকুয়াম ক্লিনার’ দেখানো হয়, বাস্তবে তা নয়।\\n২) সূর্যের জায়গায় একই ভরের ব্ল্যাক হোল বসলে গ্রহদের কক্ষপথে কোনো বদল হতো না।\\n৩) বিপদ শুরু হয় ফেরার-উপায়-নেই সীমানার (ঘটনা দিগন্ত) একদম কাছে গেলে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/goldfish-memory.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Goldfish"}]','[{"src": "/media/myth-na-sotti/myth-20-1.webp", "width": 960, "height": 1200, "alt": "ব্ল্যাক হোল সবকিছু টেনে নেয়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-20-2.webp", "width": 960, "height": 1200, "alt": "ব্ল্যাক হোল সবকিছু টেনে নেয়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-20-3.webp", "width": 960, "height": 1200, "alt": "ব্ল্যাক হোল সবকিছু টেনে নেয়, কার্ড 3"}]','2027-02-08');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (121,'myth-21','লজ্জাবতী গাছ লজ্জা পায় বলেই পাতা গুটিয়ে নেয়','“লজ্জাবতী গাছ লজ্জা পায় বলেই পাতা গুটিয়ে নেয়”, কথাটা কি সত্যি?','myth','লজ্জা নয়। ছোঁয়া পেলে পাতার গোড়ার বিশেষ অংশ থেকে সংকেত যায়, আর সেখানকার কোষের পানির চাপ কমে পাতা গুটিয়ে আসে।','["মিথ! লজ্জা নয়। ছোঁয়া পেলে পাতার গোড়ার বিশেষ অংশ থেকে সংকেত যায়, আর সেখানকার কোষের পানির চাপ কমে পাতা গুটিয়ে আসে।", "কেন এমন?\\n১) পাতার গোড়ার ফোলা অংশ ‘পালভাইনাস’ এই নড়াচড়ার জন্য দায়ী।\\n২) ছোঁয়ার সংকেত এক পাতার গোড়া থেকে অন্য পাতার গোড়ায় ছড়িয়ে যায়।\\n৩) অনেকের ধারণা, এটা শত্রুকে ভয় দেখানোর আত্মরক্ষার কৌশল, তবে এটা এখনও অনুমান।"]','[{"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Banana"}, {"label": "UF/IFAS Extension (St. Lucie County)", "url": "https://blogs.ifas.ufl.edu/stlucieco/2026/10/19/bananas-vs-plantains-similar-fruit-different-uses/"}]','[{"src": "/media/myth-na-sotti/myth-21-1.webp", "width": 960, "height": 1200, "alt": "লজ্জাবতী গাছ লজ্জা পায় বলেই পাতা গুটিয়ে নেয়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-21-2.webp", "width": 960, "height": 1200, "alt": "লজ্জাবতী গাছ লজ্জা পায় বলেই পাতা গুটিয়ে নেয়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-21-3.webp", "width": 960, "height": 1200, "alt": "লজ্জাবতী গাছ লজ্জা পায় বলেই পাতা গুটিয়ে নেয়, কার্ড 3"}]','2027-02-13');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (122,'myth-22','বিপদে উটপাখি বালিতে মাথা গুঁজে দেয়','“বিপদে উটপাখি বালিতে মাথা গুঁজে দেয়”, কথাটা কি সত্যি?','myth','উটপাখি বালিতে মাথা গুঁজে না। বিপদে তারা মাটিতে শুয়ে গলা নিচু করে রাখে, আর দরকারে লম্বা পায়ে ছুটে পালায়।','["মিথ! উটপাখি বালিতে মাথা গুঁজে না। বিপদে তারা মাটিতে শুয়ে গলা নিচু করে রাখে, আর দরকারে লম্বা পায়ে ছুটে পালায়।", "কেন এমন?\\n১) ন্যাশনাল জিওগ্রাফিক বলছে, এই ধারণা প্রায় ২ হাজার বছরের পুরনো, রোমান লেখক প্লিনির গল্প থেকে।\\n২) ডিমের যত্ন নিতে বা খেতে তারা মাথা মাটির কাছে নামায়, দূর থেকে দেখে মনে হয় বালিতে মাথা গোঁজা।\\n৩) শত্রু এলে তারা গলা মাটিতে মিশিয়ে শুয়ে পড়ে, নয়তো দৌড় দেয়।"]','[{"label": "National Geographic", "url": "https://www.nationalgeographic.com/magazine/article/they-may-look-goofy-but-ostriches-are-nobodys-fool-feature"}, {"label": "Smithsonian''s National Zoo", "url": "https://nationalzoo.si.edu/animals/ostrich"}]','[{"src": "/media/myth-na-sotti/myth-22-1.webp", "width": 960, "height": 1200, "alt": "বিপদে উটপাখি বালিতে মাথা গুঁজে দেয়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-22-2.webp", "width": 960, "height": 1200, "alt": "বিপদে উটপাখি বালিতে মাথা গুঁজে দেয়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-22-3.webp", "width": 960, "height": 1200, "alt": "বিপদে উটপাখি বালিতে মাথা গুঁজে দেয়, কার্ড 3"}]','2027-02-15');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (123,'myth-23','কচ্ছপ ইচ্ছে করলে খোলস ছেড়ে বেরিয়ে আসতে পারে','“কচ্ছপ ইচ্ছে করলে খোলস ছেড়ে বেরিয়ে আসতে পারে”, কথাটা কি সত্যি?','myth','পারে না। কচ্ছপের খোলস তার কঙ্কালেরই অংশ, পাঁজর আর মেরুদণ্ডের সাথে জোড়া।','["মিথ! পারে না। কচ্ছপের খোলস তার কঙ্কালেরই অংশ, পাঁজর আর মেরুদণ্ডের সাথে জোড়া।", "কেন এমন?\\n১) খোলসের পিঠের অংশ চ্যাপ্টা হয়ে যাওয়া পাঁজর দিয়ে তৈরি।\\n২) সেই পাঁজর মেরুদণ্ডের হাড়ের সাথে জোড়া লেগে আছে।\\n৩) তাই কার্টুনের মতো কচ্ছপকে খোলস থেকে টেনে বের করা যায় না।"]','[{"label": "Live Science", "url": "https://www.livescience.com/27322-flamingos.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Flamingo"}]','[{"src": "/media/myth-na-sotti/myth-23-1.webp", "width": 960, "height": 1200, "alt": "কচ্ছপ ইচ্ছে করলে খোলস ছেড়ে বেরিয়ে আসতে পারে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-23-2.webp", "width": 960, "height": 1200, "alt": "কচ্ছপ ইচ্ছে করলে খোলস ছেড়ে বেরিয়ে আসতে পারে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-23-3.webp", "width": 960, "height": 1200, "alt": "কচ্ছপ ইচ্ছে করলে খোলস ছেড়ে বেরিয়ে আসতে পারে, কার্ড 3"}]','2027-02-20');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (124,'myth-24','হামিংবার্ড পেছন দিকে উড়তে পারে','“হামিংবার্ড পেছন দিকে উড়তে পারে”, কথাটা কি সত্যি?','true','সত্যি! হামিংবার্ডই একমাত্র পাখি, যে সত্যিকারের পেছন দিকে উড়তে আর এক জায়গায় ভেসে থাকতে পারে।','["সত্য! সত্যি! হামিংবার্ডই একমাত্র পাখি, যে সত্যিকারের পেছন দিকে উড়তে আর এক জায়গায় ভেসে থাকতে পারে।", "কেন এমন?\\n১) অডুবন বলছে, হামিংবার্ডই একমাত্র পাখি, যে সত্যিকার অর্থে এক জায়গায় ভেসে থাকতে পারে।\\n২) তারা সামনে, পেছনে, ওপরে, নিচে আর পাশে, সব দিকেই উড়তে পারে।\\n৩) এই ওড়ার কৌশল পাখির জগতে একেবারেই আলাদা।"]','[{"label": "Audubon", "url": "https://www.audubon.org/news/hummingbird-flight-nothing-else-bird-world"}, {"label": "Audubon Adventures", "url": "https://netapp.audubon.org/AudubonAdventures/hummingbird_essay.htm"}]','[{"src": "/media/myth-na-sotti/myth-24-1.webp", "width": 960, "height": 1200, "alt": "হামিংবার্ড পেছন দিকে উড়তে পারে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-24-2.webp", "width": 960, "height": 1200, "alt": "হামিংবার্ড পেছন দিকে উড়তে পারে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-24-3.webp", "width": 960, "height": 1200, "alt": "হামিংবার্ড পেছন দিকে উড়তে পারে, কার্ড 3"}]','2027-02-22');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (125,'myth-25','হাঙরের কখনো ক্যানসার হয় না','“হাঙরের কখনো ক্যানসার হয় না”, কথাটা কি সত্যি?','myth','হয়। বিজ্ঞানীরা অনেক আগে থেকেই জানেন, হাঙরেরও ক্যানসার হয়।','["মিথ! হয়। বিজ্ঞানীরা অনেক আগে থেকেই জানেন, হাঙরেরও ক্যানসার হয়।", "কেন এমন?\\n১) এক গ্রেট হোয়াইট হাঙরের শরীরে টিউমার পাওয়া গেছে।\\n২) এই ধারণা ছড়ায় হাঙরের তরুণাস্থি বিক্রির প্রচারে।\\n৩) হাঙরের তরুণাস্থি ক্যানসার সারায়, এর কোনো প্রমাণ নেই।"]','[{"label": "NASA Science", "url": "https://science.nasa.gov/moon/top-moon-questions/"}, {"label": "NASA StarChild", "url": "https://starchild.gsfc.nasa.gov/docs/StarChild/solar_system_level2/dark_side.html"}]','[{"src": "/media/myth-na-sotti/myth-25-1.webp", "width": 960, "height": 1200, "alt": "হাঙরের কখনো ক্যানসার হয় না, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-25-2.webp", "width": 960, "height": 1200, "alt": "হাঙরের কখনো ক্যানসার হয় না, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-25-3.webp", "width": 960, "height": 1200, "alt": "হাঙরের কখনো ক্যানসার হয় না, কার্ড 3"}]','2027-02-27');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (126,'myth-26','মৌমাছি হুল ফোটালে মারা যায়','“মৌমাছি হুল ফোটালে মারা যায়”, কথাটা কি সত্যি?','partial','ভোমরা আর বোলতা বারবার হুল ফোটাতে পারে।','["আংশিক সত্য মধুর মৌমাছি সাধারণত মারা যায়, কিন্তু সব মৌমাছি বা বোলতা নয়। ভোমরা আর বোলতা বারবার হুল ফোটাতে পারে।", "কেন এমন?\\n১) মধুর মৌমাছির হুলে কাঁটা থাকে। মানুষের ত্বকে আটকে গিয়ে হুলসহ পেটের অংশ ছিঁড়ে যায়।\\n২) ভোমরা, বোলতা আর হর্নেটের হুল মসৃণ, তারা বারবার হুল ফোটাতে পারে।\\n৩) রানি মৌমাছির হুলে কাঁটা কম, সে হুল ফুটিয়েও বেঁচে থাকে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/goldfish-memory.html"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Goldfish"}]','[{"src": "/media/myth-na-sotti/myth-26-1.webp", "width": 960, "height": 1200, "alt": "মৌমাছি হুল ফোটালে মারা যায়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-26-2.webp", "width": 960, "height": 1200, "alt": "মৌমাছি হুল ফোটালে মারা যায়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-26-3.webp", "width": 960, "height": 1200, "alt": "মৌমাছি হুল ফোটালে মারা যায়, কার্ড 3"}]','2027-03-01');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (127,'myth-27','পিঁপড়া নিজের ওজনের ৫০ গুণ ভার বইতে পারে','“পিঁপড়া নিজের ওজনের ৫০ গুণ ভার বইতে পারে”, কথাটা কি সত্যি?','partial','তবে ৫০ গুণ হলো উঁচু সীমার উদাহরণ, প্রজাতিভেদে সংখ্যাটা বদলায়।','["আংশিক সত্য কিছু পিঁপড়ার ক্ষেত্রে সত্যি। তবে ৫০ গুণ হলো উঁচু সীমার উদাহরণ, প্রজাতিভেদে সংখ্যাটা বদলায়।", "কেন এমন?\\n১) ন্যাশনাল জিওগ্রাফিক বলছে, কিছু শ্রমিক পিঁপড়া নিজের ওজনের ৫০ গুণ ভার বইতে পারে।\\n২) ছোট প্রাণীর শরীরে মাংসপেশি আর বাইরের খোলস আকারের তুলনায় বেশি শক্তিশালী হয়।\\n৩) গবেষণায় কিছু প্রজাতিতে এর চেয়ে বেশিও মাপা হয়েছে, আবার অনেক ক্ষেত্রে ১০ গুণের মতো পাওয়া গেছে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/chemistry/does-honey-ever-go-bad"}, {"label": "BBC Science Focus", "url": "https://www.sciencefocus.com/science/why-doesnt-honey-go-off"}, {"label": "Wikipedia", "url": "https://en.wikipedia.org/wiki/Honey"}]','[{"src": "/media/myth-na-sotti/myth-27-1.webp", "width": 960, "height": 1200, "alt": "পিঁপড়া নিজের ওজনের ৫০ গুণ ভার বইতে পারে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-27-2.webp", "width": 960, "height": 1200, "alt": "পিঁপড়া নিজের ওজনের ৫০ গুণ ভার বইতে পারে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-27-3.webp", "width": 960, "height": 1200, "alt": "পিঁপড়া নিজের ওজনের ৫০ গুণ ভার বইতে পারে, কার্ড 3"}]','2027-03-06');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (128,'myth-28','লাল রং দেখলেই ষাঁড় খেপে যায়','“লাল রং দেখলেই ষাঁড় খেপে যায়”, কথাটা কি সত্যি?','myth','ষাঁড় খেপে কাপড়ের নড়াচড়া দেখে, লাল রং দেখে নয়।','["মিথ! ষাঁড় খেপে কাপড়ের নড়াচড়া দেখে, লাল রং দেখে নয়।", "কেন এমন?\\n১) লাইভ সায়েন্সের মতে, ষাঁড় বিরক্ত হয় ম্যাটাডরের কাপড় ঝাপটানোর নড়াচড়ায়, রঙে নয়।\\n২) গবাদি পশুর চোখে মাত্র দুই ধরনের রঙ-গ্রাহী কোষ আছে, তাই মানুষের মতো সব রং তারা দেখে না।\\n৩) একটি টেলিভিশন পরীক্ষায় ষাঁড় তিন রঙের পতাকাতেই সমানভাবে তেড়ে গিয়েছিল।"]','[{"label": "ESA", "url": "https://www.esa.int/Science_Exploration/Space_Science/Space_sensations/LISTEN_UP"}, {"label": "Live Science", "url": "https://www.livescience.com/space/what-would-space-sound-like-if-we-could-hear-it"}, {"label": "NASA Cosmicopia", "url": "https://cosmicopia.gsfc.nasa.gov/qa_sp_en.html"}]','[{"src": "/media/myth-na-sotti/myth-28-1.webp", "width": 960, "height": 1200, "alt": "লাল রং দেখলেই ষাঁড় খেপে যায়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-28-2.webp", "width": 960, "height": 1200, "alt": "লাল রং দেখলেই ষাঁড় খেপে যায়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-28-3.webp", "width": 960, "height": 1200, "alt": "লাল রং দেখলেই ষাঁড় খেপে যায়, কার্ড 3"}]','2027-03-08');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (129,'myth-29','জিহ্বার একেক জায়গায় একেক স্বাদ','“জিহ্বার একেক জায়গায় একেক স্বাদ”, কথাটা কি সত্যি?','myth','পুরো জিহ্বাই পাঁচটি মূল স্বাদের সবকটি টের পায়। জিহ্বার ‘মানচিত্র’ একটা ভুল ধারণা।','["মিথ! পুরো জিহ্বাই পাঁচটি মূল স্বাদের সবকটি টের পায়। জিহ্বার ‘মানচিত্র’ একটা ভুল ধারণা।", "কেন এমন?\\n১) জিহ্বার সব অংশে মিষ্টি, টক, নোনতা, তেতো আর উমামি স্বাদ টের পাওয়া যায়।\\n২) মানচিত্রটা এসেছে ১৯০১ সালের এক জার্মান গবেষণার ভুল ব্যাখ্যা থেকে।\\n৩) সংবেদনশীলতায় ছোটখাটো পার্থক্য আছে, কিন্তু কোনো অংশ শুধু একটি স্বাদের জন্য নয়।"]','[{"label": "Live Science", "url": "https://www.livescience.com/7113-tongue-map-tasteless-myth-debunked.html"}, {"label": "PMC", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8956797/"}]','[{"src": "/media/myth-na-sotti/myth-29-1.webp", "width": 960, "height": 1200, "alt": "জিহ্বার একেক জায়গায় একেক স্বাদ, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-29-2.webp", "width": 960, "height": 1200, "alt": "জিহ্বার একেক জায়গায় একেক স্বাদ, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-29-3.webp", "width": 960, "height": 1200, "alt": "জিহ্বার একেক জায়গায় একেক স্বাদ, কার্ড 3"}]','2027-03-13');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (130,'myth-30','কেমেলিয়ন মিশে যেতে রং বদলায়','“কেমেলিয়ন মিশে যেতে রং বদলায়”, কথাটা কি সত্যি?','myth','বেশিরভাগ ক্ষেত্রে মূল কারণ এটা নয়। রং বদলের বড় উদ্দেশ্য অন্য কেমেলিয়নের সাথে যোগাযোগ।','["মিথ! বেশিরভাগ ক্ষেত্রে মূল কারণ এটা নয়। রং বদলের বড় উদ্দেশ্য অন্য কেমেলিয়নের সাথে যোগাযোগ।", "কেন এমন?\\n১) ন্যাশনাল জিওগ্রাফিকের রিপোর্ট অনুযায়ী, উজ্জ্বল রঙের বদল মূলত সংকেত দেওয়ার জন্য।\\n২) মেজাজ, আলো আর তাপমাত্রাও রং বদলে ভূমিকা রাখে।\\n৩) লুকানোর কাজেও কিছুটা লাগে, তবে সেটা সীমিত কয়েকটা রঙের মধ্যে।"]','[{"label": "NASA", "url": "https://www.nasa.gov/vision/space/workinginspace/great_wall.html"}, {"label": "Live Science", "url": "https://www.livescience.com/34212-great-wall-of-china-only-manmade-object-visible-from-space.html"}, {"label": "Scientific American", "url": "https://www.scientificamerican.com/article/no-you-cant-see-the-great-wall-of-china-from-space/"}]','[{"src": "/media/myth-na-sotti/myth-30-1.webp", "width": 960, "height": 1200, "alt": "কেমেলিয়ন মিশে যেতে রং বদলায়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-30-2.webp", "width": 960, "height": 1200, "alt": "কেমেলিয়ন মিশে যেতে রং বদলায়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-30-3.webp", "width": 960, "height": 1200, "alt": "কেমেলিয়ন মিশে যেতে রং বদলায়, কার্ড 3"}]','2027-03-15');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (131,'myth-31','কুকুর শুধু সাদা-কালো দেখে','“কুকুর শুধু সাদা-কালো দেখে”, কথাটা কি সত্যি?','myth','কুকুর রং দেখে, তবে মানুষের মতো সব নয়। তারা মূলত নীল আর হলুদ দেখে, লাল-সবুজ ধূসরের মতো লাগে।','["মিথ! কুকুর রং দেখে, তবে মানুষের মতো সব নয়। তারা মূলত নীল আর হলুদ দেখে, লাল-সবুজ ধূসরের মতো লাগে।", "কেন এমন?\\n১) কুকুরের চোখে দুই ধরনের রঙ-গ্রাহী কোষ, মানুষের তিন ধরনের।\\n২) তাই তারা নীল আর হলুদ আলাদা করতে পারে, কিন্তু লাল আর সবুজ নয়।\\n৩) সবুজ ঘাসে লাল বল খুঁজে পেতে কুকুরের কষ্ট হতে পারে।"]','[{"label": "Live Science", "url": "https://www.livescience.com/34029-dog-color-vision.html"}, {"label": "Scientific American", "url": "https://www.scientificamerican.com/article/what-colors-do-dogs-see/"}]','[{"src": "/media/myth-na-sotti/myth-31-1.webp", "width": 960, "height": 1200, "alt": "কুকুর শুধু সাদা-কালো দেখে, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-31-2.webp", "width": 960, "height": 1200, "alt": "কুকুর শুধু সাদা-কালো দেখে, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-31-3.webp", "width": 960, "height": 1200, "alt": "কুকুর শুধু সাদা-কালো দেখে, কার্ড 3"}]','2027-03-20');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (132,'myth-32','২১ দিনেই অভ্যাস তৈরি হয়','“২১ দিনেই অভ্যাস তৈরি হয়”, কথাটা কি সত্যি?','myth','২১ দিন একটা মিথ। ইউসিএলের এক গবেষণায় অভ্যাস পাকা হতে মধ্যমান লেগেছিল ৬৬ দিন, ফারাক ছিল ১৮ থেকে ২৫৪ দিন।','["মিথ! ২১ দিন একটা মিথ। ইউসিএলের এক গবেষণায় অভ্যাস পাকা হতে মধ্যমান লেগেছিল ৬৬ দিন, ফারাক ছিল ১৮ থেকে ২৫৪ দিন।", "কেন এমন?\\n১) ৯৬ জন স্বেচ্ছাসেবক একটা দৈনিক অভ্যাস বেছে নিয়েছিলেন।\\n২) অভ্যাস স্বয়ংক্রিয় হতে সময় লেগেছে ১৮ থেকে ২৫৪ দিন, মধ্যমান ৬৬ দিন।\\n৩) গবেষকদের মতে, প্রতিদিন নিয়মিত করাটাই সবচেয়ে বড় ব্যাপার, আর কঠিন অভ্যাসে বেশি সময় লাগে।"]','[{"label": "UCL Health Chatter", "url": "https://blogs.ucl.ac.uk/bsh/2012/06/29/busting-the-21-days-habit-formation-myth/"}, {"label": "Scientific American", "url": "https://www.scientificamerican.com/article/how-long-does-it-really-take-to-form-a-habit/"}]','[{"src": "/media/myth-na-sotti/myth-32-1.webp", "width": 960, "height": 1200, "alt": "২১ দিনেই অভ্যাস তৈরি হয়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-32-2.webp", "width": 960, "height": 1200, "alt": "২১ দিনেই অভ্যাস তৈরি হয়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-32-3.webp", "width": 960, "height": 1200, "alt": "২১ দিনেই অভ্যাস তৈরি হয়, কার্ড 3"}]','2027-03-22');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (133,'myth-33','সাপ দুধ খায়','“সাপ দুধ খায়”, কথাটা কি সত্যি?','myth','সাপ দুধ খায় না। ক্ষুধার্ত আর পানিশূন্য সাপকে জোর করে দুধ দিলে বরং তার ক্ষতি হয়।','["মিথ! সাপ দুধ খায় না। ক্ষুধার্ত আর পানিশূন্য সাপকে জোর করে দুধ দিলে বরং তার ক্ষতি হয়।", "কেন এমন?\\n১) সাপ সরীসৃপ। তারা মাংসাশী, জন্মের পর মায়ের দুধ খায় না, তাই দুধ হজমের দরকারও নেই।\\n২) দুধের ল্যাকটোজ ভাঙতে ল্যাকটেজ এনজাইম লাগে। সাপের তা নেই, তাই পেটে গাঁজন হয়ে পানিশূন্যতা আর অসুস্থতা বাড়ে।\\n৩) ধারণাটা সম্ভবত এসেছে গোয়ালঘরের সাপ থেকে। সাপ আসলে ইঁদুর খুঁজছিল, দুধ নয়।"]','[{"label": "Wildlife SOS", "url": "https://news.wildlifesos.org/debunking-common-myths-surrounding-snakes/"}, {"label": "Science Insights", "url": "https://scienceinsights.org/can-snakes-drink-milk-the-science-behind-the-myth/"}]','[{"src": "/media/myth-na-sotti/myth-33-1.webp", "width": 960, "height": 1200, "alt": "সাপ দুধ খায়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-33-2.webp", "width": 960, "height": 1200, "alt": "সাপ দুধ খায়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-33-3.webp", "width": 960, "height": 1200, "alt": "সাপ দুধ খায়, কার্ড 3"}]','2027-03-27');
INSERT INTO bj_myths (id,slug,claim,question,verdict,short,body,sources,images,published_at) VALUES (134,'myth-34','হাতি ইঁদুরকে ভয় পায়','“হাতি ইঁদুরকে ভয় পায়”, কথাটা কি সত্যি?','myth','হাতি ইঁদুরকে বিশেষ ভয় পায় না। হঠাৎ ছোট দ্রুত নড়াচড়া দেখলে চমকে যেতে পারে, এটুকুই।','["মিথ! হাতি ইঁদুরকে বিশেষ ভয় পায় না। হঠাৎ ছোট দ্রুত নড়াচড়া দেখলে চমকে যেতে পারে, এটুকুই।", "কেন এমন?\\n১) ধারণাটা অন্তত রোমান যুগের, প্লিনির লেখায় এর উল্লেখ আছে।\\n২) ২০০৬ সালের এক টিভি পরীক্ষায় একটা হাতি পিছিয়ে গিয়েছিল। কিন্তু পরীক্ষাটা ছোট আর অনানুষ্ঠানিক, আরেক পরীক্ষায় সার্কাসের হাতি সাড়াই দেয়নি।\\n৩) হাতির সামনের দিকে একটা অন্ধ অংশ আছে, তাই যেকোনো ছোট দ্রুত নড়াচড়ায় তারা চমকাতে পারে। ইঁদুর শুঁড়ে ঢোকে, এর প্রমাণ নেই।"]','[{"label": "ZME Science", "url": "https://zmescience.com/science/elephants-afraid-mice"}, {"label": "Global Elephants", "url": "https://globalelephants.org/elefact-friday-of-mice-and-elephants/"}]','[{"src": "/media/myth-na-sotti/myth-34-1.webp", "width": 960, "height": 1200, "alt": "হাতি ইঁদুরকে ভয় পায়, কার্ড 1"}, {"src": "/media/myth-na-sotti/myth-34-2.webp", "width": 960, "height": 1200, "alt": "হাতি ইঁদুরকে ভয় পায়, কার্ড 2"}, {"src": "/media/myth-na-sotti/myth-34-3.webp", "width": 960, "height": 1200, "alt": "হাতি ইঁদুরকে ভয় পায়, কার্ড 3"}]','2027-03-29');
